var n=`1275-green-fig-and-saltfish`;var a=`world-1275`;var t=`LC`;var r=`central-america-caribbean`;var s=4;var o=1492;var l={en:`Green Fig and Saltfish`,ua:`Зелені банани з солоною рибою`};var d={en:`Green Fig and Saltfish is a dish from Saint Lucia featuring salt cod, banana, yellow onion, tomato. This home-sized recipe records each ingredient at the step where it is used. Use firm unripe bananas, not ripe dessert bananas, for green fig and saltfish.`,ua:`Зелені банани з солоною рибою, страва кухні країни Сент-Люсія з такими основними складниками: солона тріска, банан, жовта цибуля, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Для страви потрібні тверді недостиглі банани, а не стиглі десертні.`};var g=[{en:`Soak salt cod in cold water in the refrigerator for about 24 hours, changing the water several times. Drain before simmering; never soak salted fish at room temperature.`,ua:`Вимочуйте солону тріску в холодній воді в холодильнику близько доби, кілька разів змінюючи воду. Злийте перед варінням; не вимочуйте рибу за кімнатної температури.`,t:[`soaking-dried-produce`],m:1440,i:[[`salt-cod`,520,`g`],[`water`,1400,`ml`]]},{en:`Gently cook the prepared contents in the simmering liquid from earlier steps until fully cooked and safe to eat.`,ua:`Обережно доведіть підготовлені продукти до повної готовності в гарячій рідині з попередніх етапів.`,t:[`poaching`],m:14,i:[]},{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`banana`,650,`g`],[`water`,900,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,165,`g`],[`tomato`,260,`g`],[`garlic`,4,`clove`],[`olive-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,22,`g`]]}];var m={slug:n,id:a,country:`LC`,region:r,servings:4,minutes:o,title:l,text:d,steps:g};export{t as country,m as default,a as id,o as minutes,r as region,s as servings,n as slug,g as steps,d as text,l as title};